import{_ as e,o as i,c as s,a2 as t}from"./chunks/framework.DxqK4cCD.js";const c=JSON.parse('{"title":"工具","description":"实际使用场景明确的软件与开发资源","frontmatter":{"title":"工具","description":"实际使用场景明确的软件与开发资源","sidebar":false},"headers":[],"relativePath":"tools/index.md","filePath":"tools/index.md","lastUpdated":1786541753000}'),l={name:"tools/index.md"};function r(n,a,h,o,p,d){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h1><p>这个页面只收录用途明确、值得再次使用的工具。与单纯的收藏夹不同，每一项都会说明适用场景和选择它的理由。</p><h2 id="文档翻译" tabindex="-1">文档翻译 <a class="header-anchor" href="#文档翻译" aria-label="Permalink to &quot;文档翻译&quot;">​</a></h2><h3 id="babeldoc" tabindex="-1"><a href="https://app.immersivetranslate.com/babel-doc" target="_blank" rel="noreferrer">BabelDOC</a> <a class="header-anchor" href="#babeldoc" aria-label="Permalink to &quot;[BabelDOC](https://app.immersivetranslate.com/babel-doc)&quot;">​</a></h3><p>面向 PDF 和技术文档的双语翻译工具，适合阅读论文、手册与长篇外文资料。</p><p><strong>适合场景</strong></p><ul><li>希望保留原文版式，并对照阅读译文；</li><li>文档中包含公式、表格或多栏排版；</li><li>需要处理比浏览器网页更复杂的 PDF。</li></ul><p><strong>使用建议</strong></p><p>技术名词和代码标识符仍需结合原文确认。翻译适合降低首次阅读成本，不应代替对关键段落的核对。</p><ul><li>项目仓库：<a href="https://github.com/funstory-ai/BabelDOC" target="_blank" rel="noreferrer">funstory-ai/BabelDOC</a></li></ul><h2 id="数据可视化" tabindex="-1">数据可视化 <a class="header-anchor" href="#数据可视化" aria-label="Permalink to &quot;数据可视化&quot;">​</a></h2><h3 id="veusz" tabindex="-1"><a href="https://veusz.github.io/download/" target="_blank" rel="noreferrer">Veusz</a> <a class="header-anchor" href="#veusz" aria-label="Permalink to &quot;[Veusz](https://veusz.github.io/download/)&quot;">​</a></h3><p>面向科学数据的二维、三维绘图工具，支持通过图形界面调整图表，也能使用脚本复现绘图流程。</p><p><strong>适合场景</strong></p><ul><li>绘制实验曲线、散点图与误差线；</li><li>需要比电子表格更精细的坐标轴和排版控制；</li><li>希望将绘图配置保存下来，之后继续修改或复用。</li></ul><p><strong>选择理由</strong></p><p>它兼顾了 GUI 的即时反馈和脚本化的可重复性，适合不值得单独搭建一套 Python 绘图工程的小型数据任务。</p><ul><li>项目仓库：<a href="https://github.com/veusz/veusz" target="_blank" rel="noreferrer">veusz/veusz</a></li></ul><h2 id="网站维护" tabindex="-1">网站维护 <a class="header-anchor" href="#网站维护" aria-label="Permalink to &quot;网站维护&quot;">​</a></h2><h3 id="vitepress" tabindex="-1">VitePress <a class="header-anchor" href="#vitepress" aria-label="Permalink to &quot;VitePress&quot;">​</a></h3><p>本站使用的静态站点生成器。文章以 Markdown 保存，构建后可以直接部署到 GitHub Pages。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 本地预览</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 生成静态页面</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 检查构建结果</span></span></code></pre></div><ul><li>官方文档：<a href="https://vitepress.dev/" target="_blank" rel="noreferrer">vitepress.dev</a></li></ul><h3 id="github-actions-与-pages" tabindex="-1">GitHub Actions 与 Pages <a class="header-anchor" href="#github-actions-与-pages" aria-label="Permalink to &quot;GitHub Actions 与 Pages&quot;">​</a></h3><p>用于自动构建和部署本站。向 <code>main</code> 分支推送后，工作流会安装依赖、执行构建，并把静态产物发布到 <code>gh-pages</code>。</p><p>这套流程的价值是：内容、模板和部署配置都保存在同一个仓库中，网站可以从任意一次提交重新生成。</p><h2 id="收录标准" tabindex="-1">收录标准 <a class="header-anchor" href="#收录标准" aria-label="Permalink to &quot;收录标准&quot;">​</a></h2><p>一个工具进入这里之前，至少应该满足一项：</p><ul><li>明显节省重复劳动；</li><li>能改善结果的可验证性或可复现性；</li><li>在某个特定场景中比常见替代品更顺手；</li><li>已经实际使用过，并且知道它的局限。</li></ul><p>如果你有适合系统学习或技术写作的工具推荐，可以在<a href="/guestbook/">留言板</a>告诉我。</p>`,30)])])}const k=e(l,[["render",r]]);export{c as __pageData,k as default};
